#!/usr/bin/env bash
set +x
set -euo pipefail
test "$(id -u)" -eq 0
umask 077
/usr/bin/python3 -I -B - <<'INSTALL_AGENT1'
import base64,hashlib,os,pathlib,subprocess,tempfile
raw=base64.b64decode('')
assert hashlib.sha256(raw).hexdigest()=='ea16fb1b54647a957e2be271458d223b554d97a824dff3e9ddfb31c51132afce'
fd,path=tempfile.mkstemp(prefix='y-agent1-first-',suffix='.py')
with os.fdopen(fd,'wb') as f:f.write(raw)
try:subprocess.run(['/usr/bin/python3','-I','-B',path,'--install-run'],check=True)
finally:pathlib.Path(path).unlink()
INSTALL_AGENT1
